fn countVowels(text: Text) -> Number {
    var count: Number = 0
    for c in text.lower().chars() {
        if c.contains("a") or c.contains("e") or c.contains("i") or c.contains("o") or c.contains("u") {
            count = count + 1
        }
    }
    return count
}

test "countVowels function tests" {
  expect countVowels("banana") == 3
  expect countVowels("Apple") == 2
  expect countVowels("rhythm") == 0
  expect countVowels("") == 0
  expect countVowels("AEIOUaeiou") == 10
}

fn reverseWords(sentence: Text) -> Text {
    let words = sentence.split(" ")
    var result = ""
    for word in words {
        if result == "" {
            result = word
        } else {
            result = word + " " + result
        }
    }
    return result
}

test "reverseWords tests" {
    expect reverseWords("hello world") == "world hello"
    expect reverseWords("a b c") == "c b a"
    expect reverseWords("single") == "single"
    expect reverseWords("") == ""
    expect reverseWords("  ") == "  "
}

test "reverseWords tests" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("a b c") == "c b a"
  expect reverseWords("single") == "single"
  expect reverseWords("") == ""
  expect reverseWords("  ") == "  "
}

The failure comes from the line  

```kosika
let words = sentence.split(" ")
```

`split(" ")` removes every single space and returns only the non‑empty word tokens.  
If the input contains multiple consecutive spaces or leading/trailing spaces, those spaces are lost, so the output cannot preserve the original spacing.

**Revised algorithm**

1. Split the sentence with a regular expression that captures the whitespace as separate tokens.  
   ```kosika
   let parts = sentence.split(/(\s+)/)
   ```
   `parts` will now contain alternating word tokens and whitespace tokens.

2. Filter the word tokens, reverse their order, and keep the whitespace tokens in their original positions.  
   ```kosika
   let words = parts.filter(p => !p.isWhitespace())
   let reversedWords = words.reversed()
   ```

3. Reconstruct the string by iterating through `parts`; when a part is a word token, consume the next element from `reversedWords`, otherwise keep the whitespace token unchanged.  
   ```kosika
   var result = ""
   var wordIndex = 0
   for part in parts {
       if part.isWhitespace() {
           result += part
       } else {
           result += reversedWords[wordIndex]
           wordIndex += 1
       }
   }
   ```

This preserves the exact original spacing while reversing only the words.

fn fizzBuzz(n: Number) -> Text {
  var divisible3 = (n % 3 == 0);
  var divisible5 = (n % 5 == 0);
  if divisible3 and divisible5 {
    return "fizzbuzz";
  } else if divisible3 {
    return "fizz";
  } else if divisible5 {
    return "buzz";
  } else {
    return Text(n);
  }
}

