fn isPrime(n: Number) -> Bool {
  if n < 2 return false
  if n == 2 return true
  if n % 2 == 0 return false
  var i = 3
  while i * i <= n {
    if n % i == 0 return false
    i = i + 2
  }
  return true
}

test "prime function tests" {
  expect isPrime(2) == true
  expect isPrime(4) == false
  expect isPrime(17) == true
  expect isPrime(1) == false
  expect isPrime(0) == false
  expect isPrime(-5) == false
}

In Kosika every **function** and **control‑flow block** must be wrapped in braces `{}` and every **statement** must end with a semicolon `;`.  
The correct structure is:

```
fn functionName(params) -> ReturnType {
  // body
}
```

For `isPrime` we also need a `while` block that is delimited by `{}` and a `return` statement after the loop.  
All `if` statements that contain only a single expression can omit the `then` keyword, but the `return` still needs a semicolon.

Revised, compilable code:

```kosika
fn isPrime(n: Number) -> Bool {
  if n < 2 return false;
  if n == 2 return true;
  if n % 2 == 0 return false;
  var i = 3;
  while i * i <= n {
    if n % i == 0 return false;
    i = i + 2;
  }
  return true;
}

test "prime function tests" {
  expect isPrime(2) == true;
  expect isPrime(4) == false;
  expect isPrime(17) == true;
  expect isPrime(1) == false;
  expect isPrime(0) == false;
  expect isPrime(-5) == false;
}
```

**Verification**  
Run the test suite (`kosh run` or equivalent). The test block will evaluate each `expect` expression; if all evaluations return `true`, the compiler reports *“All tests passed”*. If any fail, it will show the failed assertion. This confirms that `isPrime` behaves correctly for the provided cases.

fn maxOrZero(lst: Number[]) -> Number {
    if lst.length() == 0 {
        return 0
    }
    var max = lst[0]
    for x in lst {
        if x > max {
            max = x
        }
    }
    return max
}

