  expect maxOrZero([3,1,5]) == 5
  expect maxOrZero([-2, -1, -3]) == -1
  expect maxOrZero([]) == 0
  expect maxOrZero([7]) == 7
  expect maxOrZero([4,4,4]) == 4
}

